from django.http import JsonResponse

PRODUCTS = [
    {'id': 1, 'name': 'Keyboard', 'category': 'electronics', 'price': 1200},
    {'id': 2, 'name': 'Mouse', 'category': 'electronics', 'price': 500},
    {'id': 3, 'name': 'Notebook', 'category': 'stationery', 'price': 80},
]

def product_list(request):
    category = request.GET.get('category')
    products = PRODUCTS if not category else [p for p in PRODUCTS if p['category'] == category]
    return JsonResponse({'products': products})

def product_detail(request, product_id):
    for product in PRODUCTS:
        if product['id'] == product_id:
            return JsonResponse(product)
    return JsonResponse({'error': 'Product not found'}, status=404)
